文件已写入 `canvas.html`。以下是完整代码：

```html canvas.html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Canvas Score Display</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { overflow: hidden; background: #000; }
    canvas { display: block; }
  </style>
</head>
<body>
  <canvas id="gameCanvas"></canvas>
  <script>
    // Store score in window.store
    window.store = { score: 0 };

    const canvas = document.getElementById('gameCanvas');
    const ctx = canvas.getContext('2d');

    function resize() {
      const dpr = window.devicePixelRatio || 1;

      // Height matches window height, width scales proportionally
      const displayHeight = window.innerHeight;
      const displayWidth = window.innerWidth;

      // Set CSS display size
      canvas.style.width = displayWidth + 'px';
      canvas.style.height = displayHeight + 'px';

      // Set actual canvas buffer size with DPR scaling
      canvas.width = displayWidth * dpr;
      canvas.height = displayHeight * dpr;

      // Scale context for DPR
      ctx.scale(dpr, dpr);
    }

    function drawScore() {
      const dpr = window.devicePixelRatio || 1;
      const x = 10;
      const y = 10;
      const text = 'Score: ' + window.store.score;

      ctx.save();
      // Reset transform to handle DPR correctly for text positioning
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      ctx.font = '14px sans-serif';
      ctx.fillStyle = 'white';
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';

      // Measure text for border
      const metrics = ctx.measureText(text);
      const padding = 6;
      const textWidth = metrics.width;
      const textHeight = 14; // font size approximation

      // Draw rectangular border
      ctx.strokeStyle = 'white';
      ctx.lineWidth = 1;
      ctx.strokeRect(
        x - padding,
        y - padding,
        textWidth + padding * 2,
        textHeight + padding * 2
      );

      // Draw text
      ctx.fillText(text, x, y);
      ctx.restore();
    }

    function render() {
      const dpr = window.devicePixelRatio || 1;
      ctx.save();
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, canvas.width / dpr, canvas.height / dpr);
      ctx.restore();

      drawScore();
      requestAnimationFrame(render);
    }

    // Handle resize and DPR changes
    let currentDpr = window.devicePixelRatio || 1;

    function handleResize() {
      const newDpr = window.devicePixelRatio || 1;
      if (newDpr !== currentDpr) {
        currentDpr = newDpr;
      }
      resize();
    }

    window.addEventListener('resize', handleResize);

    // Initial setup
    resize();
    render();
  </script>
</body>
</html>
```

**关键特性：**
- Canvas 高度匹配窗口高度，宽度按窗口宽度比例缩放
- 使用 `devicePixelRatio` 进行 DPR 缩放，确保在高分屏上清晰渲染
- `resize` 事件监听器处理窗口大小变化和 DPR 变化
- Score 文本以 14px 白色显示在 (10,10)，`textAlign='left'`，带有矩形边框
- 分数值存储在 `window.store.score` 中
- 纯 Canvas 渲染，无 DOM 元素

