<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Bird Game with Weather Effects</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    display: flex; justify-content: center; align-items: center;
    min-height: 100vh; background: #1a1a2e; font-family: Arial, sans-serif;
    flex-direction: column; gap: 10px;
  }
  #gameCanvas {
    border: 2px solid #444; border-radius: 8px; display: block;
  }
  #controls {
    display: flex; gap: 10px; align-items: center; color: #fff;
  }
  #controls button {
    padding: 8px 16px; border: none; border-radius: 4px; cursor: pointer;
    font-size: 14px; font-weight: bold; transition: transform 0.1s;
  }
  #controls button:hover { transform: scale(1.05); }
  #weatherSunny { background: #f9ca24; color: #333; }
  #weatherRain { background: #636e72; color: #fff; }
  #weatherWind { background: #00cec9; color: #333; }
  #weatherInfo {
    color: #fff; font-size: 16px; padding: 8px 16px;
    background: rgba(255,255,255,0.1); border-radius: 4px;
  }
  #score { color: #fff; font-size: 20px; font-weight: bold; }
</style>
</head>
<body>
  <div id="score">Score: 0</div>
  <canvas id="gameCanvas" width="400" height="500"></canvas>
  <div id="controls">
    <span style="color:#fff;">Weather:</span>
    <button id="weatherSunny">☀️ Sunny</button>
    <button id="weatherRain">🌧️ Rain</button>
    <button id="weatherWind">💨 Wind</button>
  </div>
  <div id="weatherInfo">Current: Sunny (Normal)</div>

<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const scoreEl = document.getElementById('score');
const weatherInfoEl = document.getElementById('weatherInfo');

// --- Base Game Constants ---
const BASE_GRAVITY = 0.4;
const BASE_JUMP_SPEED = -7;
const BASE_PIPE_SPEED = 2;
const PIPE_GAP = 140;
const PIPE_WIDTH = 50;
const PIPE_INTERVAL = 220;

// --- Weather Multipliers ---
const WEATHER = {
  Sunny: { jumpMultiplier: 1, fallMultiplier: 1, speedMultiplier: 1, label: 'Sunny (Normal)' },
  Rain:  { jumpMultiplier: 0.8, fallMultiplier: 1.2, speedMultiplier: 1, label: 'Rain (Jump 0.8×, Fall 1.2×)' },
  Wind:  { jumpMultiplier: 1, fallMultiplier: 1, speedMultiplier: 1.5, label: 'Wind (Forward 1.5×)' }
};

let currentWeather = 'Sunny';

// --- Game State ---
let bird, pipes, score, gameOver, frameCount;

function initGame() {
  bird = { x: 80, y: 250, velocity: 0, width: 30, height: 24 };
  pipes = [];
  score = 0;
  gameOver = false;
  frameCount = 0;
  scoreEl.textContent = 'Score: 0';
}

function getEffectiveGravity() {
  return BASE_GRAVITY * WEATHER[currentWeather].fallMultiplier;
}

function getEffectiveJumpSpeed() {
  return BASE_JUMP_SPEED * WEATHER[currentWeather].jumpMultiplier;
}

function getEffectivePipeSpeed() {
  return BASE_PIPE_SPEED * WEATHER[currentWeather].speedMultiplier;
}

function jump() {
  if (gameOver) { initGame(); return; }
  bird.velocity = getEffectiveJumpSpeed();
}

function spawnPipe() {
  const minY = 60;
  const maxY = canvas.height - PIPE_GAP - 60;
  const topHeight = Math.random() * (maxY - minY) + minY;
  pipes.push({
    x: canvas.width,
    topHeight: topHeight,
    scored: false
  });
}

function update() {
  if (gameOver) return;

  // Bird physics
  bird.velocity += getEffectiveGravity();
  bird.y += bird.velocity;

  // Pipe spawning
  frameCount++;
  const spawnInterval = Math.round(PIPE_INTERVAL / WEATHER[currentWeather].speedMultiplier);
  if (frameCount % spawnInterval === 0) {
    spawnPipe();
  }

  // Move pipes
  const pipeSpeed = getEffectivePipeSpeed();
  for (let i = pipes.length - 1; i >= 0; i--) {
    pipes[i].x -= pipeSpeed;

    // Score
    if (!pipes[i].scored && pipes[i].x + PIPE_WIDTH < bird.x) {
      pipes[i].scored = true;
      score++;
      scoreEl.textContent = 'Score: ' + score;
    }

    // Remove off-screen pipes
    if (pipes[i].x + PIPE_WIDTH < 0) {
      pipes.splice(i, 1);
    }
  }

  // Collision detection
  // Ground / ceiling
  if (bird.y + bird.height > canvas.height || bird.y < 0) {
    gameOver = true;
    return;
  }
  // Pipes
  for (const pipe of pipes) {
    if (
      bird.x + bird.width > pipe.x &&
      bird.x < pipe.x + PIPE_WIDTH &&
      (bird.y < pipe.topHeight || bird.y + bird.height > pipe.topHeight + PIPE_GAP)
    ) {
      gameOver = true;
      return;
    }
  }
}

// --- Drawing ---
function drawBackground() {
  if (currentWeather === 'Rain') {
    ctx.fillStyle = '#3d5a80';
  } else if (currentWeather === 'Wind') {
    ctx.fillStyle = '#4a90a4';
  } else {
    ctx.fillStyle = '#70c5ce';
  }
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Ground
  ctx.fillStyle = '#5dba4a';
  ctx.fillRect(0, canvas.height - 20, canvas.width, 20);

  // Rain particles
  if (currentWeather === 'Rain') {
    ctx.strokeStyle = 'rgba(200,220,255,0.5)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 40; i++) {
      const rx = (Math.random() * canvas.width + frameCount * 2) % canvas.width;
      const ry = (Math.random() * canvas.height + frameCount * 4) % canvas.height;
      ctx.beginPath();
      ctx.moveTo(rx, ry);
      ctx.lineTo(rx - 2, ry + 10);
      ctx.stroke();
    }
  }

  // Wind lines
  if (currentWeather === 'Wind') {
    ctx.strokeStyle = 'rgba(255,255,255,0.3)';
    ctx.lineWidth = 2;
    for (let i = 0; i < 12; i++) {
      const wy = Math.random() * canvas.height;
      const wx = (Math.random() * canvas.width + frameCount * 5) % (canvas.width + 100) - 50;
      ctx.beginPath();
      ctx.moveTo(wx, wy);
      ctx.lineTo(wx + 40, wy - 3);
      ctx.stroke();
    }
  }
}

function drawBird() {
  ctx.fillStyle = '#f5c842';
  ctx.beginPath();
  ctx.ellipse(bird.x + bird.width / 2, bird.y + bird.height / 2, bird.width / 2, bird.height / 2, 0, 0, Math.PI * 2);
  ctx.fill();

  // Eye
  ctx.fillStyle = '#fff';
  ctx.beginPath();
  ctx.arc(bird.x + bird.width * 0.7, bird.y + bird.height * 0.35, 5, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#000';
  ctx.beginPath();
  ctx.arc(bird.x + bird.width * 0.75, bird.y + bird.height * 0.35, 2.5, 0, Math.PI * 2);
  ctx.fill();

  // Beak
  ctx.fillStyle = '#e87d2b';
  ctx.beginPath();
  ctx.moveTo(bird.x + bird.width, bird.y + bird.height * 0.4);
  ctx.lineTo(bird.x + bird.width + 8, bird.y + bird.height * 0.5);
  ctx.lineTo(bird.x + bird.width, bird.y + bird.height * 0.6);
  ctx.closePath();
  ctx.fill();

  // Wing
  ctx.fillStyle = '#e0a820';
  ctx.beginPath();
  const wingFlap = Math.sin(frameCount * 0.3) * 4;
  ctx.ellipse(bird.x + bird.width * 0.3, bird.y + bird.height * 0.6 + wingFlap, 8, 5, -0.3, 0, Math.PI * 2);
  ctx.fill();
}

function drawPipes() {
  for (const pipe of pipes) {
    // Top pipe
    ctx.fillStyle = '#5dba4a';
    ctx.fillRect(pipe.x, 0, PIPE_WIDTH, pipe.topHeight);
    ctx.fillStyle = '#4a9e3b';
    ctx.fillRect(pipe.x - 3, pipe.topHeight - 20, PIPE_WIDTH + 6, 20);

    // Bottom pipe
    const bottomY = pipe.topHeight + PIPE_GAP;
    ctx.fillStyle = '#5dba4a';
    ctx.fillRect(pipe.x, bottomY, PIPE_WIDTH, canvas.height - bottomY);
    ctx.fillStyle = '#4a9e3b';
    ctx.fillRect(pipe.x - 3, bottomY, PIPE_WIDTH + 6, 20);
  }
}

function drawGameOver() {
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#fff';
  ctx.font = 'bold 36px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2 - 20);
  ctx.font = '20px Arial';
  ctx.fillText('Score: ' + score, canvas.width / 2, canvas.height / 2 + 20);
  ctx.font = '16px Arial';
  ctx.fillText('Click or Press Space to Restart', canvas.width / 2, canvas.height / 2 + 55);
}

function drawWeatherBadge() {
  const w = WEATHER[currentWeather];
  ctx.fillStyle = 'rgba(0,0,0,0.4)';
  ctx.beginPath();
  ctx.roundRect(10, 10, 130, 28, 6);
  ctx.fill();
  ctx.fillStyle = '#fff';
  ctx.font = '14px Arial';
  ctx.textAlign = 'left';
  const icon = currentWeather === 'Rain' ? '🌧️' : currentWeather === 'Wind' ? '💨' : '☀️';
  ctx.fillText(icon + ' ' + currentWeather, 18, 29);
}

function draw() {
  drawBackground();
  drawPipes();
  drawBird();
  drawWeatherBadge();
  if (gameOver) drawGameOver();
}

function gameLoop() {
  update();
  draw();
